import { SDNode } from "@/Node/SDNode";
import { RenderNode } from "@/Renderer/RenderNode";
import { PacketColor, SDColor } from "@/Utility/Color";

/**
 * Array 基类，为所有数组类组件提供基础功能实现。
 * 
 * 此组件是一个抽象基类，不应该被直接实例化。它为所有类似于数组的组件提供了统一的
 * 数据管理和操作接口。每个元素（element）都是一个 SDNode，按照线性结构组织，
 * 可以通过下标进行访问和操作。
 * 
 * 特性：
 * - 线性存储：元素按顺序存储，支持随机访问。
 * - 灵活下标：支持自定义起始下标。
 * - 统一接口：提供增删改查等标准数组操作。
 * - 动画支持：元素操作自动触发相应的动画效果。
 */
export class BaseArray extends SDNode {
    constructor(parent: SDNode | RenderNode);

    /**
     * 获取数组的起始下标。
     * 
     * 起始下标定义了数组的第一个元素的逻辑位置。例如，如果起始下标为 1，
     * 那么数组的第一个元素的下标就是 1 而不是 0。这在某些特定的应用场景
     * （如教育演示、算法可视化）中特别有用。
     * 
     * 使用场景：
     * - 获取当前的下标起点。
     * - 计算元素的实际位置。
     * - 在遍历数组前确认范围。
     * 
     * @returns 当前的起始下标。
     */
    start(): number;

    /**
     * 设置数组的起始下标。
     * 
     * 修改起始下标会影响到所有元素的逻辑位置，但不会改变它们的物理存储顺序。
     * 这个操作通常用于调整数组的显示方式，使其符合特定的展示需求。
     * 
     * 使用场景：
     * - 从 1 开始计数的数组表示。
     * - 特定算法的下标对齐。
     * - 自定义数组范围的显示。
     * 
     * @param start 新的起始下标。
     * @returns this 用于支持链式调用。
     */
    start(start: number): this;

    /**
     * 获取数组的结束下标。
     * 
     * 结束下标表示数组中最后一个元素的位置。这个值会随着数组长度的变化
     * 而动态更新。计算公式为：起始下标 + 长度 - 1。
     * 
     * 使用场景：
     * - 确定数组的范围。
     * - 计算遍历的终点。
     * - 验证下标是否越界。
     * 
     * @returns 当前的结束下标。
     */
    end(): number;

    /**
     * 获取数组的当前长度。
     * 
     * 长度表示数组中实际存在的元素个数，与起始下标无关。例如，一个长度为 3
     * 的数组，即使起始下标是 5，它依然只包含 3 个元素。
     * 
     * 使用场景：
     * - 获取元素总数。
     * - 计算数组容量。
     * - 判断数组是否为空。
     * 
     * @returns 当前的数组长度。
     */
    length(): number;

    /**
     * 设置数组的长度。
     * 
     * 此操作会根据新的长度值自动调整数组的大小：
     * - 增加长度：在数组末尾添加空元素。
     * - 减少长度：从末尾开始删除多余的元素。
     * 
     * 使用场景：
     * - 预分配数组空间。
     * - 截断多余的元素。
     * - 确保数组大小符合要求。
     * 
     * @param length 要设置的新长度。
     * @returns this 用于支持链式调用。
     */
    length(length: number): this;

    /**
     * 设置数组的长度。
     * 
     * 此方法提供了一个更直观的接口来调整数组大小：
     * - 增加长度：自动在末尾填充空元素。
     * - 减少长度：从末尾开始移除元素。
     * 
     * 使用场景：
     * - 动态调整数组大小。
     * - 预留空间以待使用。
     * - 清理多余的元素。
     * 
     * @param length 要设置的新长度。
     * @returns this 用于支持链式调用。
     */
    resize(length: number): this;

    /**
     * 将逻辑下标转换为物理下标。
     * 
     * 在数组内部，元素按照从 0 开始的物理下标存储。但对外部使用者来说，
     * 可能需要使用不同的起始下标（逻辑下标）。此方法提供了两者之间的转换。
     * 
     * 示例：
     * - 如果起始下标为 3，那么：
     *   - 逻辑下标 3 对应物理下标 0
     *   - 逻辑下标 4 对应物理下标 1
     *   - 以此类推
     * 
     * 使用场景：
     * - 自定义下标系统的实现。
     * - 数组内部位置计算。
     * - 下标映射和转换。
     * 
     * @param id 要转换的逻辑下标。
     * @returns 对应的物理下标。
     */
    idx(id: number): number;

    /**
     * 查找指定元素在数组中的逻辑下标。
     * 
     * 从数组中查找给定元素的位置，返回其逻辑下标。这个过程会考虑数组的
     * 起始下标设置，确保返回的是正确的逻辑位置。
     * 
     * 注意事项：
     * - 如果元素不存在，返回 -1。
     * - 如果数组中存在多个相同元素，返回第一个匹配项的下标。
     * 
     * 使用场景：
     * - 元素位置查找。
     * - 重复元素检测。
     * - 元素存在性验证。
     * 
     * @param element 要查找的元素。
     * @returns 元素的逻辑下标，如果未找到则返回 -1。
     */
    indexOf(element: SDNode): number;

    /**
     * 获取指定下标位置的元素。
     * 
     * 根据给定的逻辑下标，返回对应位置的元素。此方法会自动处理下标转换，
     * 使用者只需要关心逻辑下标即可。
     * 
     * 注意事项：
     * - 下标必须在有效范围内。
     * - 返回的是元素的引用，对其的修改会直接影响数组。
     * 
     * 使用场景：
     * - 访问特定位置的元素。
     * - 元素查询和获取。
     * - 元素状态检查。
     * 
     * @param id 要获取元素的逻辑下标。
     * @returns 指定位置的元素。
     */
    element(id: number): SDNode;

    /**
     * 获取数组中的所有元素。
     * 
     * 返回一个包含所有元素的数组副本。这些元素按照它们在数组中的物理顺序排列，
     * 而不考虑逻辑下标的设置。
     * 
     * 特性：
     * - 返回数组的浅拷贝。
     * - 保持元素的原始顺序。
     * - 包含所有非空元素。
     * 
     * 使用场景：
     * - 整体元素处理。
     * - 数组遍历操作。
     * - 元素集合获取。
     * 
     * @returns 包含所有元素的数组。
     */
    elements(): Array<SDNode>;

    /**
     * 获取 Array 指定下标对应的 element
     * @param id 指定下标
     */
    element(id: number): SDNode;

    /**
     * 获取 Array 中的所有 element
     */
    elements(): Array<SDNode>;

    /**
     * 获取数组中最后一个元素。
     * 
     * 此方法提供了快速访问数组末尾元素的方式，常用于栈操作或需要访问
     * 最新添加元素的场景。
     * 
     * 注意事项：
     * - 数组不能为空。
     * - 返回的是元素的引用。
     * 
     * 使用场景：
     * - 栈顶元素访问。
     * - 最新元素检查。
     * - 末尾元素状态验证。
     * 
     * @returns 数组中的最后一个元素。
     */
    lastElement(): SDNode;

    /**
     * 获取数组中第一个元素。
     * 
     * 此方法提供了快速访问数组开头元素的方式，常用于队列操作或需要访问
     * 最早添加元素的场景。
     * 
     * 注意事项：
     * - 数组不能为空。
     * - 返回的是元素的引用。
     * 
     * 使用场景：
     * - 队列头部访问。
     * - 起始元素检查。
     * - 首个元素状态验证。
     * 
     * @returns 数组中的第一个元素。
     */
    firstElement(): SDNode;

    /**
     * 遍历数组中的所有元素。
     * 
     * 为每个元素执行指定的回调函数，回调函数可以访问当前元素及其逻辑下标。
     * 遍历顺序按照元素在数组中的物理顺序进行。
     * 
     * 特性：
     * - 按序遍历所有元素。
     * - 提供元素和下标信息。
     * - 支持链式调用。
     * 
     * 使用场景：
     * - 批量元素处理。
     * - 元素状态更新。
     * - 数据收集和统计。
     * 
     * @param callback 处理每个元素的回调函数，接收当前元素和其逻辑下标作为参数。
     * @returns this 用于支持链式调用。
     */
    forEachElement(callback: (element: SDNode, id: number) => void): this;

    /**
     * 在指定位置插入新元素。
     * 
     * 在给定的逻辑下标位置创建并插入一个新元素。新元素的值由参数指定，
     * 元素的创建过程由方法内部自动完成。
     * 
     * 注意事项：
     * - 插入位置必须在有效范围内。
     * - 插入操作会自动移动现有元素。
     * - 支持动画效果。
     * 
     * 使用场景：
     * - 数组元素插入。
     * - 有序序列维护。
     * - 动态内容添加。
     * 
     * @param id 要插入新元素的逻辑下标。
     * @param value 新元素的值。
     * @returns this 用于支持链式调用。
     */
    insert(id: number, value: any): this;

    /**
     * 在指定位置插入已存在的元素。
     * 
     * 将场景中已存在的元素直接插入到数组的指定位置。在动画表现上，
     * 该元素会从其当前位置移动到数组内的目标位置。
     * 
     * 特性：
     * - 直接移动元素。
     * - 保持元素状态。
     * - 自动处理动画。
     * 
     * 使用场景：
     * - 元素位置调整。
     * - 跨容器元素移动。
     * - 动画化的布局变更。
     * 
     * @param id 要插入元素的逻辑下标。
     * @param element 要插入的已存在元素。
     * @returns this 用于支持链式调用。
     */
    insertFromExistElement(id: number, element: SDNode): this;

    /**
     * 在数组末尾添加新元素。
     * 
     * 创建一个新元素并将其添加到数组的末尾。新元素的值由参数指定，
     * 元素的创建过程由方法内部自动完成。这是最常用的添加元素的方法。
     * 
     * 特性：
     * - 自动创建元素。
     * - 末尾快速添加。
     * - 支持任意值类型。
     * 
     * 使用场景：
     * - 动态数据添加。
     * - 列表内容扩展。
     * - 序列数据构建。
     * 
     * @param value 新元素的值。
     * @returns this 用于支持链式调用。
     */
    push(value: any): this;

    /**
     * 批量添加多个元素到数组末尾。
     * 
     * 将一个普通数组中的所有元素依次添加到当前数组的末尾。每个数组元素
     * 都会被作为值来创建新的数组元素。
     * 
     * 特性：
     * - 批量处理。
     * - 自动值转换。
     * - 保持添加顺序。
     * 
     * 使用场景：
     * - 批量数据导入。
     * - 数组合并操作。
     * - 初始数据填充。
     * 
     * @param array 包含要添加元素值的数组。
     * @returns this 用于支持链式调用。
     */
    pushArray(array: Array<any>): this;

    /**
     * 使用已存在的值创建并添加新元素到数组末尾。
     * 
     * 使用场景中已存在的节点值创建新元素并添加到数组末尾。在动画表现上，
     * 该值会从其当前位置移动到新创建的元素内部。
     * 
     * 特性：
     * - 复用已有节点。
     * - 自动处理动画。
     * - 末尾快速添加。
     * 
     * 使用场景：
     * - 元素迁移。
     * - 动态内容重组。
     * - 可视化数据流动。
     * 
     * @param value 要作为新元素值的已存在节点。
     * @returns this 用于支持链式调用。
     */
    pushFromExistValue(value: SDNode): this;

    /**
     * 将已存在的元素添加到数组末尾。
     * 
     * 将场景中已存在的元素直接添加到数组的末尾。在动画表现上，
     * 该元素会从其当前位置移动到数组的末尾位置。
     * 
     * 特性：
     * - 直接移动元素。
     * - 保持元素状态。
     * - 动画化过渡。
     * 
     * 使用场景：
     * - 元素归集。
     * - 跨容器迁移。
     * - 动态布局调整。
     * 
     * @param element 要添加的已存在元素。
     * @returns this 用于支持链式调用。
     */
    pushFromExistElement(element: SDNode): this;

    /**
     * 删除数组末尾的元素。
     * 
     * 移除并销毁数组最后一个元素。此操作会导致元素从场景中完全消失，
     * 包括其可能包含的所有子元素。
     * 
     * 注意事项：
     * - 数组不能为空。
     * - 操作不可逆。
     * - 会触发删除动画。
     * 
     * 使用场景：
     * - 栈操作实现。
     * - 序列尾部清理。
     * - 动态内容移除。
     * 
     * @returns this 用于支持链式调用。
     */
    pop(): this;

    /**
     * 删除指定位置的元素。
     * 
     * 移除并销毁数组中指定下标位置的元素。此操作会导致该元素从场景中
     * 完全消失，包括其可能包含的所有子元素。
     * 
     * 注意事项：
     * - 下标必须有效。
     * - 操作不可逆。
     * - 会重排后续元素。
     * 
     * 使用场景：
     * - 定点元素删除。
     * - 无效数据清理。
     * - 动态内容更新。
     * 
     * @param id 要删除元素的逻辑下标。
     * @returns this 用于支持链式调用。
     */
    erase(id: number): this;

    /**
     * 移除指定位置的元素但不销毁。
     * 
     * 将指定下标位置的元素从数组中移除，但保留该元素在场景中的存在。
     * 这使得该元素可以被重新使用或移动到其他位置。
     * 
     * 特性：
     * - 保留元素实例。
     * - 自动重排序列。
     * - 返回移除的元素。
     * 
     * 使用场景：
     * - 元素重定位。
     * - 临时元素移除。
     * - 动态布局调整。
     * 
     * @param id 要移除元素的逻辑下标。
     * @returns 被移除的元素。
     */
    dropElement(id: number): SDNode;

    /**
     * 移除第一个元素但不销毁。
     * 
     * 将数组的第一个元素移除，但保留该元素在场景中的存在。常用于
     * 队列操作或需要重用首个元素的场景。
     * 
     * 特性：
     * - 保留元素实例。
     * - 自动前移序列。
     * - 返回移除的元素。
     * 
     * 使用场景：
     * - 队列操作实现。
     * - 首元素重定位。
     * - 序列头部调整。
     * 
     * @returns 被移除的第一个元素。
     */
    dropFirstElement(): SDNode;

    /**
     * 移除最后一个元素但不销毁。
     * 
     * 将数组的最后一个元素移除，但保留该元素在场景中的存在。常用于
     * 栈操作或需要重用末尾元素的场景。
     * 
     * 特性：
     * - 保留元素实例。
     * - 无需重排序列。
     * - 返回移除的元素。
     * 
     * 使用场景：
     * - 栈操作实现。
     * - 末尾元素重定位。
     * - 动态序列调整。
     * 
     * @returns 被移除的最后一个元素。
     */
    dropLastElement(): SDNode;

    /**
     * 移除指定元素的值但保留元素。
     * 
     * 清除指定下标位置元素的值，但保留元素本身在数组中的位置。这个操作
     * 会将元素重置为空状态，但不会影响数组的结构。
     * 
     * 特性：
     * - 保留元素位置。
     * - 返回移除的值。
     * - 元素变为空容器。
     * 
     * 使用场景：
     * - 元素值重置。
     * - 数据清理。
     * - 占位符创建。
     * 
     * @param id 要清除值的元素的逻辑下标。
     * @returns 被移除的值。
     */
    dropValue(id: number): SDNode;

    /**
     * 获取指定位置元素的值。
     * 
     * 返回数组中指定下标位置元素所包含的值。这个值可以是任意类型的节点。
     * 
     * 使用场景：
     * - 元素值的读取。
     * - 数据验证。
     * - 状态检查。
     * 
     * @param id 要获取值的元素的逻辑下标。
     * @returns 元素包含的值。
     */
    value(id: number): SDNode;

    /**
     * 设置指定位置元素的值。
     * 
     * 更新数组中指定下标位置元素的值。如果元素已有值，原有值将被替换。
     * 
     * 特性：
     * - 自动更新显示。
     * - 触发值变更动画。
     * - 保持元素位置。
     * 
     * @param id 要设置值的元素的逻辑下标。
     * @param value 要设置的新值。
     * @returns this 用于支持链式调用。
     */
    value(id: number, value: SDNode): this;

    /**
     * 获取指定位置元素的文本内容。
     * 
     * 返回数组中指定下标位置元素值的文本表示。
     * 
     * 使用场景：
     * - 文本内容读取。
     * - 显示内容获取。
     * - 数据展示准备。
     * 
     * @param id 要获取文本的元素的逻辑下标。
     * @returns 元素的文本内容。
     */
    text(id: number): string;

    /**
     * 设置指定位置元素的文本内容。
     * 
     * 更新数组中指定下标位置元素的文本内容。这会改变元素的显示文本。
     * 
     * 特性：
     * - 自动更新显示。
     * - 支持任意文本。
     * - 保持其他属性。
     * 
     * @param id 要设置文本的元素的逻辑下标。
     * @param text 要设置的新文本内容。
     * @returns this 用于支持链式调用。
     */
    text(id: number, text: string): this;

    /**
     * 获取指定位置元素的数值。
     * 
     * 尝试将指定下标位置元素的文本内容转换为数值。
     * 
     * 使用场景：
     * - 数值计算。
     * - 排序比较。
     * - 数据分析。
     * 
     * @param id 要获取数值的元素的逻辑下标。
     * @returns 转换后的数值，转换失败则返回 NaN。
     */
    intValue(id: number): number;

    /**
     * 获取指定位置元素的不透明度。
     * 
     * 返回数组中指定下标位置元素的当前不透明度值。
     * 
     * @param id 要获取不透明度的元素的逻辑下标。
     * @returns 不透明度值（0-1之间）。
     */
    opacity(id: number): number;

    /**
     * 设置指定位置元素的不透明度。
     * 
     * 更新数组中指定下标位置元素的不透明度。这会影响元素的视觉显示效果。
     * 
     * 特性：
     * - 动画化过渡。
     * - 即时视觉反馈。
     * 
     * @param id 要设置不透明度的元素的逻辑下标。
     * @param opacity 新的不透明度值（0-1之间）。
     * @returns this 用于支持链式调用。
     */
    opacity(id: number, opacity: number): this;

    /**
     * 设置所有元素的颜色。
     * 
     * 将数组中所有元素的颜色统一设置为指定颜色。
     * 
     * 特性：
     * - 批量颜色更新。
     * - 动画化过渡。
     * 
     * @param color 要设置的颜色。
     * @returns this 用于支持链式调用。
     */
    color(color: SDColor): this;

    /**
     * 获取指定位置元素的颜色。
     * 
     * 返回数组中指定下标位置元素的当前颜色。
     * 
     * @param id 要获取颜色的元素的逻辑下标。
     * @returns 元素的当前颜色。
     */
    color(id: number): PacketColor;

    /**
     * 设置指定位置元素的颜色。
     * 
     * 更新数组中指定下标位置元素的颜色。
     * 
     * 特性：
     * - 动画化过渡。
     * - 即时视觉反馈。
     * 
     * @param id 要设置颜色的元素的逻辑下标。
     * @param color 要设置的新颜色。
     * @returns this 用于支持链式调用。
     */
    color(id: number, color: SDColor): this;

    /**
     * 设置指定区间内元素的颜色。
     * 
     * 将数组中指定区间范围内的所有元素颜色设置为给定颜色。
     * 
     * 特性：
     * - 区间批量更新。
     * - 动画化过渡。
     * - 范围可控制。
     * 
     * @param l 区间起始位置（包含）。
     * @param r 区间结束位置（包含）。
     * @param color 要设置的新颜色。
     * @returns this 用于支持链式调用。
     */
    color(l: number, r: number, color: SDColor): this;

    /**
     * 对数组元素进行排序。
     * 
     * 使用指定的比较器函数对数组中的所有元素进行排序。如果未提供比较器，
     * 则默认按元素的数值大小升序排序。
     * 
     * 特性：
     * - 动画化排序过程。
     * - 自定义排序规则。
     * - 保持元素完整性。
     * 
     * @param comparator 可选的比较器函数。
     * @returns this 用于支持链式调用。
     */
    sort(comparator?: (a: SDNode, b: SDNode) => number): this;

    /**
     * 对数组指定区间的元素进行排序。
     * 
     * 使用指定的比较器函数对数组中指定区间范围内的元素进行排序。
     * 
     * 特性：
     * - 局部排序。
     * - 动画化过程。
     * - 范围可控制。
     * 
     * @param l 排序区间起始位置（包含）。
     * @param r 排序区间结束位置（包含）。
     * @param comparator 可选的比较器函数。
     * @returns this 用于支持链式调用。
     */
    sort(l: number, r: number, comparator?: (a: SDNode, b: SDNode) => number): this;
}
